package com.inventra.backend.security;
import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Base64;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService {private final String secret;private final long expirySeconds;public JwtService(@Value("${inventra.jwt.secret:inventra-development-secret-change-me}") String s,@Value("${inventra.jwt.expiry-seconds:86400}") long e){secret=s;expirySeconds=e;}public String generateToken(String email){long now=Instant.now().getEpochSecond();String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}");String p=b64("{\"sub\":\""+escape(email)+"\",\"exp\":"+(now+expirySeconds)+"}");return h+"."+p+"."+sign(h+"."+p);}public boolean isTokenValid(String token){try{String[] a=token.split("\\.");if(a.length!=3||!constant(sign(a[0]+"."+a[1]),a[2]))return false;String p=new String(Base64.getUrlDecoder().decode(a[1]),StandardCharsets.UTF_8);int i=p.indexOf("\"exp\":");if(i<0)return false;int start=i+6,end=start;while(end<p.length()&&Character.isDigit(p.charAt(end)))end++;long exp=Long.parseLong(p.substring(start,end));return Instant.now().getEpochSecond()<exp;}catch(Exception e){return false;}}public String extractEmail(String token){String[] a=token.split("\\.");String p=new String(Base64.getUrlDecoder().decode(a[1]),StandardCharsets.UTF_8);String marker="\"sub\":\"";int i=p.indexOf(marker);if(i<0)throw new IllegalArgumentException("Invalid token");int s=i+marker.length(),e=p.indexOf('\"',s);return p.substring(s,e);}private String sign(String s){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("Unable to sign JWT",e);}}private String b64(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));}private boolean constant(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}private String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"");}}
